import {platforms,phase3Platforms,createBabyState,FLOOR_Y} from '../../../../src/js/config.js';
import {getDarkRoomFeet} from '../../../../src/js/environment/DarkRoomContact.js';
const ensure=(value,label)=>{if(!value)throw Error(label);};
export function geometry() {
 const g=review.game,c=g.platformContact;let checks=0,walkingFrames=0;
 const rows=[];
 for(const phase3 of [false,true])for(const [index,p] of (phase3?phase3Platforms:platforms).entries()){
  const b=c.bounds(p);ensure(b.heights,'Perfil derivado da arte carregada '+p.style);
  rows.push({phase3,index,style:p.style,x:b.x,right:b.right,width:b.right-b.x,old:p.standRegion?.w??p.w});
  for(let center=b.x;center<b.right;center+=2)for(const dt of [.5,1,1.2]){
   const baby={...createBabyState(),x:center-19,vx:0,vy:12,onGround:false};
   const top=c.height(p,getDarkRoomFeet(baby,{isPhase3:phase3}));if(!Number.isFinite(top))continue;
   baby.y=top+1-baby.h;ensure(c.resolve(baby,{isPhase3:phase3},[p],dt)?.index===0,'Descida sobre desenho '+p.style);
   baby.vy=-12;ensure(!c.resolve(baby,{isPhase3:phase3},[p],dt),'Não gruda na subida');
   baby.vy=12;baby.y+=12*dt;ensure(!c.resolve(baby,{isPhase3:phase3},[p],dt),'Não captura por baixo');checks+=3;
  }
 }
 // Caminhada real de produção cruza a antiga lacuna nos dois modos e três passos de tempo.
 for(const difficulty of ['NORMAL','EASY'])for(const dt of [.5,1,1.2]){
  g.review.prepare(0,250);g.state.gameDifficulty=difficulty;g.state.gameplayState='GAMEPLAY_NORMAL';g.state.firstJumpTutorialCompleted=true;
  for(let frame=0;g.state.baby.x<465&&frame<500;frame++){
   g.review.step(dt);ensure(g.state.baby.onGround,'Caiu entre urso e livros: '+g.state.baby.x);ensure(!g.isGameOver(),'Derrota na união');walkingFrames++;
  }
  ensure(g.state.baby.currentPlatformIndex===1,'Chegada aos livros sem salto');
 }
 return {checks,walkingFrames,rows};
}
export function routes(){
 const g=review.game,c=g.platformContact,rows=[];
 for(const phase3 of [false,true])for(const difficulty of ['NORMAL','EASY'])for(const dt of [.5,1,1.2])for(let target=0;target<(phase3?16:22);target++){
  const group=phase3?phase3Platforms:platforms,from=target?c.bounds(group[target-1]):phase3?{x:4170,right:4640,y:FLOOR_Y}:{x:60,right:220,y:FLOOR_Y};
  const positions=[];for(let x=from.x-34;x<from.right;x+=2)positions.push(x);
  const middle=(from.x+from.right-38)/2;positions.sort((a,b)=>Math.abs(a-middle)-Math.abs(b-middle));
  let success=null;
  for(const x of positions){
   g.review.prepare(target-1,x,phase3);g.state.gameDifficulty=difficulty;g.state.gameplayState='GAMEPLAY_NORMAL';g.state.firstJumpTutorialCompleted=true;
   const b=g.state.baby;
   if(target){const top=c.height(group[target-1],getDarkRoomFeet(b,g.state));if(!Number.isFinite(top))continue;b.y=top-b.h;}
   g.review.jump();ensure(!b.onGround,'Comando de salto aceito');
   for(let frame=0;frame<240;frame++){
    g.review.step(dt);if(g.isGameOver())break;
    if(b.onGround){if(b.currentPlatformIndex===target)success={phase3,difficulty,dt,target,launchX:x,frames:frame+1,feet:b.y+b.h};break;}
   }
   if(success)break;
  }
  ensure(success,'Sem travessia viável '+JSON.stringify({phase3,difficulty,dt,target}));rows.push(success);
 }
 return rows;
}
export function prepareInput(index,x,phase3=false){
 const g=review.game;g.review.prepare(index,x,phase3);g.state.gameDifficulty='NORMAL';g.state.gameplayState='GAMEPLAY_NORMAL';g.state.firstJumpTutorialCompleted=true;g.state.lastJumpTime=-10000;
 const top=g.platformContact.height((phase3?phase3Platforms:platforms)[index],getDarkRoomFeet(g.state.baby,g.state));g.state.baby.y=top-g.state.baby.h;
 g.review.step(1);ensure(g.state.baby.onGround,'Apoio deve existir antes da entrada');g.review.renderManual();
 return {...g.state.baby};
}
export function scene(index,phase3=false){const g=review.game,p=(phase3?phase3Platforms:platforms)[index],bounds=g.platformContact.bounds(p);g.review.prepare(index,bounds.x+(bounds.right-bounds.x-38)/2,phase3);g.state.baby.y=g.platformContact.height(p,getDarkRoomFeet(g.state.baby,g.state))-44;g.review.draw();}
